function safeUrl(value, hostname = source.hostname) {
  if (!value) return '';
  try {
    const url = new URL(value, source);
    return url.protocol === 'https:' && url.hostname === hostname ? url.href : '';
  } catch {
    return '';
  }
}

function esc(value) {
  return String(value).replace(/[&<>"']/g, char => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
  })[char]);
}

async function upstream(path) {
  const response = await fetch(new URL(path, source), {
    signal: AbortSignal.timeout(6500),
    cf: { cacheEverything: true, cacheTtlByStatus: { '200-299': 90, '400-599': 0 } }
  });
  if (!response.ok) throw new Error('Catalog origin returned ' + response.status);
  return response;
}

async function catalog() {
  const categories = [];
  const products = [];
  const rewriter = new HTMLRewriter()
    .on('a.category-item', { element(el) { categories.push({ href: safeUrl(el.getAttribute('href')), name: '' }); } })
    .on('a.category-item h3', { text(chunk) { categories.at(-1).name += chunk.text; } })
    .on('.product-card a.product-image', { element(el) { products.push({ href: safeUrl(el.getAttribute('href')), price: '' }); } })
    .on('.product-card a.product-image img', { element(el) {
      const product = products.at(-1);
      product.image = safeUrl(el.getAttribute('data-src') || el.getAttribute('src'));
      product.name = el.getAttribute('alt');
    } })
    .on('.product-card .product-price', { text(chunk) { const product = products.at(-1); if (product) product.price += chunk.text; } });
  await rewriter.transform(await upstream('/')).text();
  return {
    categories: categories.filter(({href, name}) => href && name.trim()),
    products: products.filter(({href, image, name}) => href && image && name)
  };
}

async function buyingLink() {
  let link = '';
  const reader = new HTMLRewriter().on('a.platform-option', { element(el) {
    const href = safeUrl(el.getAttribute('href'), 'kakobuy.com');
    if (href && new URL(href).pathname === '/item/details') link ||= href;
  } });
  await reader.transform(await upstream(sample)).text();
  return link;
}

